<script setup>
import { onMounted, onBeforeUnmount, ref, watch } from 'vue';
import { usePage } from '@inertiajs/vue3';
import AdminNavigation from '@/Components/Admin/AdminNavigation.vue';
const compact=ref(false),drawer=ref(null),opened=ref(false),page=usePage();
let previousOverflow,desktop;
function close(){drawer.value?.close();opened.value=false;}
function open(){drawer.value?.showModal();opened.value=true;}
function resize(){if(desktop?.matches)close();}
function toggle(){compact.value=!compact.value;try{localStorage.setItem('aadi-admin-compact',String(compact.value));}catch{}}
watch(opened,value=>{if(value){previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';}else if(previousOverflow!==undefined){document.body.style.overflow=previousOverflow;previousOverflow=undefined;}});
watch(()=>page.url,close);
onMounted(()=>{try{compact.value=localStorage.getItem('aadi-admin-compact')==='true';}catch{}desktop=matchMedia('(min-width: 1024px)');desktop.addEventListener('change',resize);});
onBeforeUnmount(()=>{desktop?.removeEventListener('change',resize);if(previousOverflow!==undefined)document.body.style.overflow=previousOverflow;});
</script>
<template><div class="admin-shell" :class="{'admin-compact':compact}"><a class="admin-skip" href="#admin-content">Skip to content</a><aside class="admin-sidebar"><AdminNavigation :compact="compact"/><button type="button" class="admin-collapse" :aria-expanded="!compact" :aria-label="compact?'Expand sidebar':'Collapse sidebar'" @click="toggle">{{ compact?'→':'← Collapse sidebar' }}</button></aside><dialog id="admin-drawer" ref="drawer" class="admin-drawer" aria-label="Admin menu" @close="opened=false" @click="event=>{if(event.target===drawer)close();}"><button type="button" class="admin-close" aria-label="Close admin menu" autofocus @click="close">×</button><AdminNavigation/></dialog><div class="admin-body"><header class="admin-header"><button type="button" class="admin-menu" aria-label="Open admin menu" aria-controls="admin-drawer" :aria-expanded="opened" @click="open">☰</button><div class="admin-header-content"><slot name="header"><h1>Administration</h1></slot></div></header><main id="admin-content" tabindex="-1" class="admin-main"><slot/></main></div></div></template>
<style scoped>
.admin-shell{min-height:100dvh;background:#f3f6f5;color:#183e3b;font-family:Quicksand,sans-serif;--sidebar-width:252px}.admin-compact{--sidebar-width:80px}.admin-sidebar{position:fixed;inset:0 auto 0 0;width:var(--sidebar-width);display:flex;flex-direction:column;background:#103f3b;z-index:30}.admin-sidebar :deep(.admin-navigation){min-height:0;flex:1}.admin-collapse{flex-shrink:0;min-height:44px;color:#d7eeea;border-top:1px solid #ffffff24;font-size:12px;cursor:pointer}.admin-body{margin-left:var(--sidebar-width);min-width:0}.admin-header{display:flex;align-items:center;gap:14px;padding:22px 28px;background:white;border-bottom:1px solid #dce7e4}.admin-header-content{flex:1;min-width:0}.admin-main{padding:28px;min-width:0;overflow-x:auto}.admin-menu{display:none}.admin-drawer{margin:0;border:0;padding:0;width:min(290px,90vw);height:100dvh;max-height:100dvh;background:#103f3b;color:white}.admin-drawer::backdrop{background:#082c2970}.admin-drawer :deep(.admin-navigation){height:calc(100% - 44px)}.admin-close{display:block;margin-left:auto;width:44px;height:44px;font-size:26px}.admin-skip{position:fixed;top:-80px;left:16px;background:white;padding:12px;z-index:100}.admin-skip:focus{top:12px}.admin-shell button:focus-visible{outline:2px solid #f5b56f;outline-offset:-3px}@media(max-width:1023px){.admin-sidebar{display:none}.admin-body{margin-left:0}.admin-menu{display:block;width:44px;height:44px;font-size:24px;flex-shrink:0}.admin-header{padding:14px 16px}.admin-main{padding:20px 16px}}
</style>
